    {% if not any_fail.v %}<p class="muted small">No per-case failures recorded{{ " (no reference answers)" if not f.table.refs }}.</p>{% endif %}
  </div>
</div>
{% if f.journal %}
<div class="section-title" id="agent-journal"><h2>Agent journal</h2><span class="src">{{ file(f.results) }} · {{ f.journal|length }} entries, each with its focus area</span></div>
<ul class="journal">
  {% for e in f.journal %}<li{% if e.anchor %} id="journal-{{ e.area }}"{% endif %}><code>{{ e.name }}</code> → <span class="focus"{% if e.recorded != e.area %} title="recorded as {{ e.recorded }} before the retag"{% endif %}>{{ e.label }}</span>{% if e.reason %} <span class="why">{{ e.reason|truncate(120, True, "…") }}</span>{% endif %}</li>
  {% endfor %}
</ul>
{% endif %}

