    return (f"Net saving: ${today:,.2f}/mo → ${recommended:,.2f}/mo = "
            f"${saved:,.2f}/mo saved. Check cost once at {spend_note(check_cost, attempts)} "
            f"(list). First-month ROI: ${saved - check_cost:,.2f}.")

